import React, { useState } from 'react';
import { Box, Typography, Button, TextField, InputAdornment, IconButton, Paper } from '@mui/material';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';

export default function App() {
  const [showPassword, setShowPassword] = useState(false);
  const [form, setForm] = useState({ brand: '', email: '', password: '' });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleClickShowPassword = () => setShowPassword((show) => !show);

  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        bgcolor: '#111',
      }}
    >
      <Paper
        elevation={6}
        sx={{
          display: 'flex',
          width: { xs: '95vw', md: 900 },
          minHeight: 500,
          borderRadius: 4,
          overflow: 'hidden',
        }}
      >
        {/* Left Side - Login Info */}
        <Box
          sx={{
            flex: 1,
            bgcolor: 'linear-gradient(135deg, #a8ffce 0%, #00e676 100%)',
            color: '#111',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            p: 4,
          }}
        >
          <Typography variant="h5" fontWeight={700} mb={2} align="center" sx={{ color: '#111' }}>
            Already a Hub Box Family Member ?
          </Typography>
          <Typography variant="body1" mb={3} align="center" sx={{ color: '#222' }}>
            If you are already a member of Hub Box Family then please click on "Login" button to enter your details and Login.
          </Typography>
          <Button variant="outlined" sx={{ color: '#111', borderColor: '#00e676', fontWeight: 600, borderRadius: 2, px: 4, '&:hover': { bgcolor: '#00e67622', borderColor: '#00e676', color: '#111' } }}>
            LOG IN
          </Button>
        </Box>
        {/* Right Side - Signup Form */}
        <Box
          sx={{
            flex: 1.2,
            bgcolor: '#fff',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            p: 4,
          }}
        >
          <Typography variant="h6" color="#00b050" fontWeight={700} mb={1} align="center">
            Welcome @
          </Typography>
          <Typography variant="h3" fontWeight={900} mb={2} align="center" sx={{ color: '#00b050', letterSpacing: 1 }}>
            Hub<span style={{ color: '#111' }}>Box</span>
          </Typography>
          <Typography variant="h5" fontWeight={700} mb={2} align="center">
            Create Account
          </Typography>
          <TextField
            label="Brand Name"
            name="brand"
            value={form.brand}
            onChange={handleChange}
            fullWidth
            sx={{ mb: 2 }}
          />
          <TextField
            label="Email"
            name="email"
            value={form.email}
            onChange={handleChange}
            fullWidth
            sx={{ mb: 2 }}
          />
          <TextField
            label="Password"
            name="password"
            type={showPassword ? 'text' : 'password'}
            value={form.password}
            onChange={handleChange}
            fullWidth
            sx={{ mb: 2 }}
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <IconButton onClick={handleClickShowPassword} edge="end">
                    {showPassword ? <VisibilityOff /> : <Visibility />}
                  </IconButton>
                </InputAdornment>
              ),
            }}
          />
          <Button
            variant="contained"
            fullWidth
            sx={{
              mt: 1,
              bgcolor: '#00b050',
              color: '#fff',
              fontWeight: 700,
              borderRadius: 2,
              py: 1.2,
              fontSize: 18,
              boxShadow: '0 2px 12px #00b05044',
              '&:hover': { bgcolor: '#00913a' },
            }}
          >
            Join Hub Box Family
          </Button>
          <Typography variant="body2" color="text.secondary" align="center" mt={2}>
            By joining, I agree to <span style={{ color: '#00b050', fontWeight: 600 }}>Terms of Service</span> and <span style={{ color: '#00b050', fontWeight: 600 }}>Privacy Policy</span>.
          </Typography>
        </Box>
      </Paper>
    </Box>
  );
}
